export function projectArtifactContent(
  bytes: Buffer,
  mediaType: string,
  options: { limit?: number; offset?: number } = {},
): ArtifactContentProjection {
  const sample = bytes.subarray(0, 8_192);
  const binary = !isTextMediaType(mediaType) && isBinaryContent(sample, bytes.length > sample.length);
  if (binary) {
    return { binary: true, encoding: "binary", mediaType, size: bytes.length, truncated: false };
  }

  const truncated = bytes.length > MAX_ARTIFACT_TEXT_BYTES;
  const text = bytes.subarray(0, MAX_ARTIFACT_TEXT_BYTES).toString("utf8");
  const lines = splitKeepingLineEndings(text);
  const startLine = Math.max(1, Math.trunc(options.offset ?? 1));
  const limit = Math.max(1, Math.trunc(options.limit ?? DEFAULT_TOOL_OUTPUT_MAX_LINES));

  // Slice by line, then re-bound by bytes so a caller-chosen limit — or one
  // very wide line, as in a single-line JSON artifact — cannot exceed the page
  // budget.
  const requested = lines.slice(startLine - 1, startLine - 1 + limit).join("");
  const page = boundText(requested, { keep: "head", maxBytes: DEFAULT_READ_PAGE_MAX_BYTES, maxLines: limit });
  const pageLines = page.totalLines - page.omittedLines;
  const endLine = startLine + pageLines - 1;
  const hasMore = endLine < lines.length || truncated || page.partialLine;
  return {
    binary: false,
    content: page.text,
    encoding: "utf8",
    mediaType,
    page: {
      bytes: Buffer.byteLength(page.text, "utf8"),
      endLine,
      hasMore,
      ...(hasMore ? { nextOffset: endLine + 1 } : {}),
      partialLine: page.partialLine,
      startLine,
      totalLines: lines.length,
    },
    size: bytes.length,
    truncated,
  };
}

export function projectArtifactContent(
  bytes: Buffer,
  mediaType: string,
  options: { limit?: number; offset?: number } = {},
): ArtifactContentProjection {
  const sample = bytes.subarray(0, 8_192);
  const binary = !isTextMediaType(mediaType) && isBinaryContent(sample, bytes.length > sample.length);
  if (binary) {
    return { binary: true, encoding: "binary", mediaType, size: bytes.length, truncated: false };
  }

  const truncated = bytes.length > MAX_ARTIFACT_TEXT_BYTES;
  const text = bytes.subarray(0, MAX_ARTIFACT_TEXT_BYTES).toString("utf8");
  const lines = splitKeepingLineEndings(text);
  const startLine = Math.max(1, Math.trunc(options.offset ?? 1));
  const limit = Math.max(1, Math.trunc(options.limit ?? DEFAULT_TOOL_OUTPUT_MAX_LINES));

  // Slice by line, then re-bound by bytes so a caller-chosen limit — or one
  // very wide line, as in a single-line JSON artifact — cannot exceed the page
  // budget.
  const requested = lines.slice(startLine - 1, startLine - 1 + limit).join("");
  const page = boundText(requested, { keep: "head", maxBytes: DEFAULT_READ_PAGE_MAX_BYTES, maxLines: limit });
  const pageLines = page.totalLines - page.omittedLines;
  const endLine = startLine + pageLines - 1;
  // `hasMore` states one thing only: that line paging can still advance inside
  // the decodable window. Folding `truncated` or `partialLine` in here would
  // promise a next page that no offset can reach — past the window `nextOffset`
  // would equal the offset just used, and the model would page forever.
  const hasMore = endLine < lines.length;
  const note = describeUnreachable(lines.length, truncated, page.partialLine, startLine, bytes.length);
  return {
    binary: false,
    content: page.text,
    encoding: "utf8",
    mediaType,
    ...(note ? { note } : {}),
    page: {
      bytes: Buffer.byteLength(page.text, "utf8"),
      endLine,
      hasMore,
      ...(hasMore ? { nextOffset: endLine + 1 } : {}),
      partialLine: page.partialLine,
      startLine,
      totalLines: lines.length,
    },
    size: bytes.length,
    truncated,
  };
}

/**
 * Whatever the line protocol cannot address has to be said out loud, because
 * `hasMore: false` on its own reads as "you have seen everything".
 */
function describeUnreachable(
  windowLines: number,
  truncated: boolean,
  partialLine: boolean,
  startLine: number,
  size: number,
): string | undefined {
  const notes: string[] = [];
  if (truncated) {
    notes.push(
      `Only the first ${MAX_ARTIFACT_TEXT_BYTES} bytes of this ${size}-byte version are readable as text,`
      + ` which is ${windowLines} lines; offset cannot reach past line ${windowLines}.`
      + " Process the rest with run_python or run_shell.",
    );
  }
  if (partialLine) {
    notes.push(
      `Line ${startLine} is wider than one page and was cut. Line offsets cannot address the rest of that`
      + " line; read it with run_python or run_shell instead.",
    );
  }
  return notes.length ? notes.join(" ") : undefined;
}

/** Capture authoritative domain tables. Legacy execution blobs become strong State Pool refs. */
export function versioningAuthorities(store: SessionStore, sessionId: string, runId: string): () => Promise<unknown> {
  const legacy = new CasStore(store.dataDir);
  const retained = new Map<string, Promise<ObjectRef>>();
  const retain = (ref: CasObjectRef, pool: Pool = "agent-state") => {
    const key = `${pool}:${ref.hash}:${ref.size}`;
    let saved = retained.get(key);
    if (!saved) { saved = legacy.retain(ref, pool); retained.set(key, saved); }
    return saved;
  };
  return async () => {
    const session = store.getSession(sessionId);
    const executions = await Promise.all((await store.listExecutionRuns(sessionId))
      .filter((execution) => execution.turnId === runId).map(async (execution) => ({
        ...execution,
        code: await retain(execution.code), stdout: await retain(execution.stdout), stderr: await retain(execution.stderr),
        envSnapshot: execution.envSnapshot ? await retain(execution.envSnapshot) : null,
      })));
    return {
      session: session ? { id: session.id, projectId: session.projectId } : null,
      permission: store.getSessionPermissionEpoch(sessionId) ?? null,
      artifacts: await Promise.all(store.listArtifacts(sessionId).map(async (artifact) => ({
        ...artifact, versions: await Promise.all(store.listArtifactVersions(sessionId, artifact.id).map(async (version) => ({
          ...version, content: await retain(version.content, "data"),
        }))),
      }))),
      environments: store.listEnvironments(),
      environmentRevisions: store.listEnvironmentRevisions(),
      children: store.listSubagents(sessionId),
      notifications: store.notifications.snapshot(sessionId),
      transfers: store.transfers.snapshot(sessionId),
      shellExecutions: store.shellExecutions.snapshot(sessionId),
      reviews: await store.listReviews(sessionId),
      artifactReviews: await store.listArtifactReviews(sessionId),
      executions,
    };
  };
}

/** Native task ownership, independent of which executor runs the Agent. */
export interface AgentAuthorityScope {
  sessionId: string;
  executionId: string;
  /** Absent for the session's main Agent; native tasks currently form one level. */
  subagentId?: string;
}

/** Capture shared resources and only this Agent's execution authorities. */
export function versioningAuthorities(store: SessionStore, scope: AgentAuthorityScope) {
  const { sessionId, executionId, subagentId } = scope;
  const agentId = subagentId === undefined ? "main" : `subagent:${subagentId}`;
  const legacy = new CasStore(store.dataDir);
  const retained = new Map<string, Promise<ObjectRef>>();
  const retain = (ref: CasObjectRef, pool: Pool = "agent-state") => {
    const key = `${pool}:${ref.hash}:${ref.size}`;
    let saved = retained.get(key);
    if (!saved) { saved = legacy.retain(ref, pool); retained.set(key, saved); }
    return saved;
  };
  return async () => {
    const session = store.getSession(sessionId);
    const executions = await Promise.all((await store.listExecutionRuns(sessionId))
      .filter((execution) => execution.turnId === executionId).map(async (execution) => ({
        ...execution,
        code: await retain(execution.code), stdout: await retain(execution.stdout), stderr: await retain(execution.stderr),
        envSnapshot: execution.envSnapshot ? await retain(execution.envSnapshot) : null,
      })));
    const subagents = await store.captureSubagentAuthorities(sessionId, subagentId);
    return {
      scope: { ...scope, agentId },
      session: session ? { id: session.id, projectId: session.projectId } : null,
      permission: store.getSessionPermissionEpoch(sessionId) ?? null,
      artifacts: await Promise.all(store.listArtifacts(sessionId).map(async (artifact) => ({
        ...artifact, versions: await Promise.all(store.listArtifactVersions(sessionId, artifact.id).map(async (version) => ({
          ...version, content: await retain(version.content, "data"),
        }))),
      }))),
      environments: store.listEnvironments(),
      environmentRevisions: store.listEnvironmentRevisions(),
      // The native parent owns the task catalog. A child records its own task,
      // never the session-wide sibling catalog. Full records remain auditable.
      children: subagentId === undefined ? subagents : [],
      task: subagentId === undefined ? null : subagents[0],
      notifications: store.notifications.snapshot(sessionId, agentId),
      transfers: store.transfers.snapshot(sessionId, agentId),
      shellExecutions: store.shellExecutions.snapshot(sessionId, agentId),
      reviews: await store.listReviews(sessionId),
      artifactReviews: await store.listArtifactReviews(sessionId),
      executions,
    };
  };
}
